INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (123, '8JT2', 'lemma', 'One-sided bound for the Taylor coefficients', 'Let $\psi$ be a primitive character and $0 < \theta < 1$, and suppose that, for arbitrarily large $Y$,
\[ \mathcal G_\psi(x) \le x^\theta \qquad (Y \le x \le Y^{3/2}). \]
Let $\sigma = 336$ and $A_k(s) = \frac{(-1)^k}{k!}\,\mathcal H_\psi^{(k)}(s)$. There is a constant $C$ such that, for infinitely many $k$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le C\,(\sigma - \theta)^{-k} \qquad \text{for all } \tau \in \R. \]', NULL, 104, 11, 'published', 0, 1, '2026-11-24 16:40:00', '2026-11-24 16:40:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '123', 1, 'interval-criterion-proof-2026-11-24', '{"tag":"8JT2","type":"lemma","title":"One-sided bound for the Taylor coefficients","statement_tex":"Let $\\psi$ be a primitive character and $0 < \\theta < 1$, and suppose that, for arbitrarily large $Y$,\n\\[ \\mathcal G_\\psi(x) \\le x^\\theta \\qquad (Y \\le x \\le Y^{3/2}). \\]\nLet $\\sigma = 336$ and $A_k(s) = \\frac{(-1)^k}{k!}\\,\\mathcal H_\\psi^{(k)}(s)$. There is a constant $C$ such that, for infinitely many $k$,\n\\[ |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le C\\,(\\sigma - \\theta)^{-k} \\qquad \\text{for all } \\tau \\in \\R. \\]","section_id":104,"position":11,"listed":0,"aliases":["one-sided-taylor-bound"]}', 'claude');
