INSERT INTO proofs (id, result_id, position, body_tex, body_html_cache, status, generated_by, generator_detail, reviewed_by, review_notes, created_at, updated_at, created_by, updated_by) VALUES (109, 123, 1, 'Put $g(u) = \mathcal G_\psi(e^u)$ and $K_k(u) = u^k e^{-\sigma u}/k!$. By \ref{8JS3}, $g$ is real with $|g(u)| \le C_\psi e^{2u}$, and differentiating $\mathcal H_\psi(s) = \int_0^\infty g(u)\, e^{-su}\,du$ under the integral gives
\[ A_k(\sigma + i\tau) = \int_0^\infty g(u)\, K_k(u)\, e^{-i\tau u}\,du. \]

\emph{Only an upper bound for $g$ matters.} Since $K_k \ge 0$ and $|g| + g = 2g_+$ with $g_+ = \max(g, 0)$,
\[ |A_k(\sigma + i\tau)| + \Re A_k(\sigma) \le \int_0^\infty (|g| + g)\, K_k = 2\int_0^\infty g_+ K_k. \]

\emph{The kernel sits in the window.} Take $Y$ from the hypothesis, $U = \log Y$ and $k = \lceil \frac54 \sigma U \rceil$. Then $K_k$ peaks at $u = k/\sigma \approx \frac54 U$, the middle of $[U, \frac32 U]$, where $g_+(u) \le e^{\theta u}$. As $\int_0^\infty e^{au} K_k(u)\,du = (\sigma - a)^{-k-1}$ for $a < \sigma$, the window contributes at most $(\sigma - \theta)^{-k-1}$.

\emph{The tails are negligible.} Outside the window we only know $g_+ \le C_\psi e^{2u}$. Insert $e^{\lambda(U-u)} \ge 1$ for $u < U$ and $e^{\lambda(u - 3U/2)} \ge 1$ for $u > \frac32 U$, with $\lambda = 14$, and use $\frac45 (k-1)/\sigma \le U \le \frac45 k/\sigma$:
\begin{align*}
\int_0^U e^{2u} K_k &\le e^{\lambda U} (\sigma + \lambda - 2)^{-k-1} \le \sigma^{-k} \Bigl(\frac{e^{4\lambda/(5\sigma)}\, \sigma}{\sigma + \lambda - 2}\Bigr)^{k}, \\
\int_{3U/2}^\infty e^{2u} K_k &\le e^{-3\lambda U/2} (\sigma - \lambda - 2)^{-k-1} \le \sigma^{-k} \Bigl(\frac{e^{-6\lambda/(5\sigma)}\, \sigma}{\sigma - \lambda - 2}\Bigr)^{k}.
\end{align*}
For $\sigma = 336$ the two brackets are $0.9983$ and $0.9988$, so the tails contribute at most $2C_\psi \sigma^{-k} \le 2C_\psi (\sigma - \theta)^{-k}$. The point is that the a priori growth $e^{2u}$ costs only a factor $e^{O(k/\sigma)}$, while the mass of $K_k$ outside the window is smaller by a factor $e^{-ck}$ with $c$ independent of $\sigma$; any large enough $\sigma$ works.

As $Y \to \infty$ these $k$ are unbounded, which gives the claim.', NULL, 'ai_generated', 'claude', 'claude-opus-5-5', NULL, NULL, '2026-11-24 16:40:00', '2026-11-24 16:40:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '109', 1, 'interval-criterion-proof-2026-11-24', '{"result_id":123,"body_tex":"Put $g(u) = \\mathcal G_\\psi(e^u)$ and $K_k(u) = u^k e^{-\\sigma u}/k!$. By \\ref{8JS3}, $g$ is real with $|g(u)| \\le C_\\psi e^{2u}$, and differentiating $\\mathcal H_\\psi(s) = \\int_0^\\infty g(u)\\, e^{-su}\\,du$ under the integral gives\n\\[ A_k(\\sigma + i\\tau) = \\int_0^\\infty g(u)\\, K_k(u)\\, e^{-i\\tau u}\\,du. \\]\n\n\\emph{Only an upper bound for $g$ matters.} Since $K_k \\ge 0$ and $|g| + g = 2g_+$ with $g_+ = \\max(g, 0)$,\n\\[ |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le \\int_0^\\infty (|g| + g)\\, K_k = 2\\int_0^\\infty g_+ K_k. \\]\n\n\\emph{The kernel sits in the window.} Take $Y$ from the hypothesis, $U = \\log Y$ and $k = \\lceil \\frac54 \\sigma U \\rceil$. Then $K_k$ peaks at $u = k/\\sigma \\approx \\frac54 U$, the middle of $[U, \\frac32 U]$, where $g_+(u) \\le e^{\\theta u}$. As $\\int_0^\\infty e^{au} K_k(u)\\,du = (\\sigma - a)^{-k-1}$ for $a < \\sigma$, the window contributes at most $(\\sigma - \\theta)^{-k-1}$.\n\n\\emph{The tails are negligible.} Outside the window we only know $g_+ \\le C_\\psi e^{2u}$. Insert $e^{\\lambda(U-u)} \\ge 1$ for $u < U$ and $e^{\\lambda(u - 3U/2)} \\ge 1$ for $u > \\frac32 U$, with $\\lambda = 14$, and use $\\frac45 (k-1)/\\sigma \\le U \\le \\frac45 k/\\sigma$:\n\\begin{align*}\n\\int_0^U e^{2u} K_k &\\le e^{\\lambda U} (\\sigma + \\lambda - 2)^{-k-1} \\le \\sigma^{-k} \\Bigl(\\frac{e^{4\\lambda/(5\\sigma)}\\, \\sigma}{\\sigma + \\lambda - 2}\\Bigr)^{k}, \\\\\n\\int_{3U/2}^\\infty e^{2u} K_k &\\le e^{-3\\lambda U/2} (\\sigma - \\lambda - 2)^{-k-1} \\le \\sigma^{-k} \\Bigl(\\frac{e^{-6\\lambda/(5\\sigma)}\\, \\sigma}{\\sigma - \\lambda - 2}\\Bigr)^{k}.\n\\end{align*}\nFor $\\sigma = 336$ the two brackets are $0.9983$ and $0.9988$, so the tails contribute at most $2C_\\psi \\sigma^{-k} \\le 2C_\\psi (\\sigma - \\theta)^{-k}$. The point is that the a priori growth $e^{2u}$ costs only a factor $e^{O(k/\\sigma)}$, while the mass of $K_k$ outside the window is smaller by a factor $e^{-ck}$ with $c$ independent of $\\sigma$; any large enough $\\sigma$ works.\n\nAs $Y \\to \\infty$ these $k$ are unbounded, which gives the claim.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
